// Tests of what counts as crediting a coding agent in a commit or a pull request (credit.mjs). npm run check runs them.
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { creditLines, creditProblems } from './credit.mjs';

const found = text => creditLines(text).map(each => each.line);

test('a co-author that is an agent is a credit', () => {
  assert.deepEqual(found('fix: a thing (#1)\n\nCo-Authored-By: Claude <noreply@anthropic.com>'), [3]);
  assert.deepEqual(found('co-authored-by: Codex <codex@openai.com>'), [1]);
  assert.deepEqual(found('Co-authored-by: Someone <bot@example.com>\nCo-authored-by: Copilot <x@users.noreply.github.com>'), [2]);
});

test('a line about what it was made with is a credit, and so is the footer\'s sign', () => {
  assert.deepEqual(found('## Limitations\n\nNone\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)'), [5]);
  assert.deepEqual(found('Generated with Claude Code'), [1]);
  assert.deepEqual(found('This was written by an AI assistant.'), [1]);
  assert.deepEqual(found('Made with Codex'), [1]);
  assert.deepEqual(found('AI-assisted change'), [1]);
  assert.deepEqual(found('Created using Gemini CLI'), [1]);
});

test('a credit inside Markdown emphasis is a credit, and a name with an underscore in it is none', () => {
  assert.deepEqual(found('None\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_'), [4]);
  assert.deepEqual(found('__Made with Codex__'), [1]);
  assert.deepEqual(found('*Written by an AI assistant*'), [1]);
  assert.deepEqual(found('_Co-Authored-By: Claude <noreply@anthropic.com>_'), [1]);
  assert.deepEqual(found('fix: `enemy_ai` is written by the kit, made with partner_ai in mind (#3)'), []);
  assert.deepEqual(found('_The clips prove made, written by the tools._'), []);
});

test('a person as co-author, and words that only sound like it, are no credit', () => {
  assert.deepEqual(found('Co-Authored-By: Ana Example <1+ana@users.noreply.github.com>'), []);
  assert.deepEqual(found('fix: the command\'s copy for Claude Code is written again (#1)'), []);
  assert.deepEqual(found('feat: a recording made with a start point, generated by route (#2)'), []);
  assert.deepEqual(found('The clips prove made, written by the tools, with the main menu.'), []);
  assert.deepEqual(found('Tested in OpenCode and Codex, with the command typed by hand.'), []);
  assert.deepEqual(found(''), []);
  assert.deepEqual(found(null), []);
});

test('each one found is said with where it is', () => {
  assert.deepEqual(creditProblems([
    { where: 'Commit 1234abcd', text: 'fix: a thing (#1)\n\nCo-Authored-By: Claude <noreply@anthropic.com>' },
    { where: 'The pull request\'s description', text: 'Nothing to see.' },
  ]), ['Commit 1234abcd, line 3: "Co-Authored-By: Claude <noreply@anthropic.com>"']);
});
